CREATE TABLE parcel_archive_versions(operation TEXT NOT NULL,body_hash TEXT NOT NULL,body TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(operation,body_hash));
CREATE TABLE parcel_archived_receipts(id TEXT PRIMARY KEY,body BLOB NOT NULL,raw_hash TEXT NOT NULL);
CREATE TABLE parcel_archives(id TEXT PRIMARY KEY,admission TEXT NOT NULL UNIQUE,observation TEXT NOT NULL UNIQUE,body TEXT NOT NULL,body_hash TEXT NOT NULL,archived_at TEXT NOT NULL);
CREATE TABLE parcel_audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,event TEXT NOT NULL,owner TEXT NOT NULL,detail TEXT NOT NULL);
CREATE TABLE parcel_commands(id TEXT PRIMARY KEY,hash TEXT NOT NULL,receipt TEXT NOT NULL);
CREATE TABLE parcel_configuration_audit(id TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE parcel_history_index(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,admission TEXT NOT NULL UNIQUE,observation TEXT NOT NULL UNIQUE,position TEXT NOT NULL);
CREATE TABLE parcel_history_projection(id TEXT PRIMARY KEY,barcode TEXT,state TEXT,observed REAL,wcs TEXT,plc TEXT,upload TEXT,capture TEXT,accepted INTEGER,unknown INTEGER,physical INTEGER,attempts INTEGER);
CREATE TABLE parcel_identity_conflicts(id TEXT PRIMARY KEY,body TEXT NOT NULL,acknowledged INTEGER NOT NULL DEFAULT 0);
CREATE TABLE parcel_ingress(id TEXT PRIMARY KEY,position TEXT NOT NULL,received_at TEXT NOT NULL,state TEXT NOT NULL,body TEXT NOT NULL,body_hash TEXT NOT NULL,detail TEXT,session TEXT NOT NULL,started_at TEXT,completed_at TEXT,queue_ms REAL,processing_ms REAL);
CREATE TABLE parcel_ingress_audits(input TEXT NOT NULL,seq INTEGER NOT NULL,PRIMARY KEY(input,seq));
CREATE TABLE parcel_integration_id_owners(id INTEGER PRIMARY KEY CHECK(id>0),operation TEXT NOT NULL UNIQUE,request TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL);
CREATE TABLE parcel_integration_id_ranges(binding_hash TEXT PRIMARY KEY,first_id INTEGER NOT NULL CHECK(first_id>0),last_id INTEGER NOT NULL CHECK(last_id>=first_id));
CREATE TABLE parcel_integration_id_restores(identity TEXT PRIMARY KEY,ceiling INTEGER NOT NULL CHECK(ceiling>=0));
CREATE TABLE parcel_measurements(id TEXT PRIMARY KEY,admission TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE parcel_meta(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,paused INTEGER NOT NULL);
CREATE TABLE parcel_operations(id TEXT PRIMARY KEY,admission TEXT NOT NULL UNIQUE,observation TEXT NOT NULL UNIQUE,body TEXT NOT NULL);
CREATE TABLE parcel_overload_ack(identity TEXT PRIMARY KEY,command TEXT NOT NULL);
CREATE TABLE parcel_receipt_custody(occurrence TEXT PRIMARY KEY,query_occurrence TEXT,observed_at TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE TABLE parcel_receipts(id TEXT PRIMARY KEY,operation TEXT NOT NULL,stage TEXT NOT NULL,request TEXT NOT NULL,source TEXT NOT NULL,state TEXT NOT NULL,raw_hash TEXT);
CREATE TABLE parcel_reply_identities(request TEXT NOT NULL,id TEXT NOT NULL,hash TEXT NOT NULL,PRIMARY KEY(request,id));
CREATE TABLE station_metric_buckets(shift TEXT NOT NULL,minute TEXT NOT NULL,position TEXT NOT NULL,recognitions INTEGER NOT NULL CHECK(recognitions>=0),requests INTEGER NOT NULL CHECK(requests>=0),assigned INTEGER NOT NULL CHECK(assigned>=0),rejected INTEGER NOT NULL CHECK(rejected>=0),unknown_count INTEGER NOT NULL CHECK(unknown_count>=0),manual_requests INTEGER NOT NULL CHECK(manual_requests>=0),PRIMARY KEY(shift,minute,position));
CREATE TABLE parcel_retention_runs(id TEXT PRIMARY KEY,at TEXT NOT NULL,days INTEGER NOT NULL,cutoff TEXT NOT NULL,backup_hash TEXT NOT NULL,summary TEXT NOT NULL);
CREATE TABLE parcel_retired_inputs(id TEXT PRIMARY KEY,body_hash TEXT NOT NULL,state TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE parcel_retired_measurements(id TEXT PRIMARY KEY,admission TEXT NOT NULL,body_hash TEXT NOT NULL);
CREATE TABLE parcel_retired_operations(id TEXT PRIMARY KEY,body_hash TEXT NOT NULL,at TEXT NOT NULL,run TEXT NOT NULL);
CREATE INDEX parcel_archives_recovery ON parcel_archives(id) WHERE json_extract(body,'$.RecoveryRequired')=1;
CREATE INDEX parcel_audit_input_operation ON parcel_audit(json_extract(detail,'$.OperationId')) WHERE event='InputObserved' AND json_valid(detail);
CREATE INDEX parcel_audit_owner_at ON parcel_audit(owner,at);
CREATE INDEX parcel_commands_pending ON parcel_commands(id) WHERE json_extract(receipt,'$.Status')='Pending';
CREATE INDEX parcel_history_barcode ON parcel_history_projection(barcode,id);
CREATE INDEX parcel_history_capture ON parcel_history_projection(capture,id);
CREATE INDEX parcel_history_observed ON parcel_history_projection(observed,id);
CREATE INDEX parcel_history_plc ON parcel_history_projection(plc,id);
CREATE INDEX parcel_history_position ON parcel_history_index(position,seq);
CREATE INDEX parcel_history_state ON parcel_history_projection(state,id);
CREATE INDEX parcel_history_upload ON parcel_history_projection(upload,id);
CREATE INDEX parcel_history_wcs ON parcel_history_projection(wcs,id);
CREATE INDEX parcel_ingress_pending ON parcel_ingress(state,position,received_at);
CREATE INDEX parcel_ingress_session ON parcel_ingress(session,received_at,position);
CREATE INDEX parcel_operations_recovery ON parcel_operations(id) WHERE json_extract(body,'$.RecoveryRequired')=1;
CREATE INDEX parcel_receipts_operation ON parcel_receipts(operation);
CREATE INDEX parcel_receipts_pending ON parcel_receipts(state,operation,stage);
CREATE TRIGGER parcel_archives_projection_insert AFTER INSERT ON parcel_archives BEGIN INSERT INTO parcel_history_projection(id,barcode,state,observed,wcs,plc,upload,capture,accepted,unknown,physical,attempts) VALUES(NEW.id,json_extract(NEW.body,'$.ParcelCode'),json_extract(NEW.body,'$.State'),julianday(json_extract(NEW.body,'$.ObservedAt')),json_extract(NEW.body,'$.Wcs.Request.Id'),json_extract(NEW.body,'$.Plc.Request.Id'),json_extract(NEW.body,'$.Upload.Request.Id'),json_extract(NEW.body,'$.Capture.Request.Id'),coalesce(json_extract(NEW.body,'$.Wcs.State')='Accepted',0),coalesce(json_extract(NEW.body,'$.Wcs.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Plc.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Upload.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Capture.State')='Unknown',0),json_extract(NEW.body,'$.State')='PhysicalCompleted',coalesce(json_extract(NEW.body,'$.Wcs.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Plc.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Upload.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Capture.Attempts'),0)) ON CONFLICT(id) DO UPDATE SET barcode=excluded.barcode,state=excluded.state,observed=excluded.observed,wcs=excluded.wcs,plc=excluded.plc,upload=excluded.upload,capture=excluded.capture,accepted=excluded.accepted,unknown=excluded.unknown,physical=excluded.physical,attempts=excluded.attempts; END;
CREATE TRIGGER parcel_archives_projection_update AFTER UPDATE ON parcel_archives BEGIN INSERT INTO parcel_history_projection(id,barcode,state,observed,wcs,plc,upload,capture,accepted,unknown,physical,attempts) VALUES(NEW.id,json_extract(NEW.body,'$.ParcelCode'),json_extract(NEW.body,'$.State'),julianday(json_extract(NEW.body,'$.ObservedAt')),json_extract(NEW.body,'$.Wcs.Request.Id'),json_extract(NEW.body,'$.Plc.Request.Id'),json_extract(NEW.body,'$.Upload.Request.Id'),json_extract(NEW.body,'$.Capture.Request.Id'),coalesce(json_extract(NEW.body,'$.Wcs.State')='Accepted',0),coalesce(json_extract(NEW.body,'$.Wcs.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Plc.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Upload.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Capture.State')='Unknown',0),json_extract(NEW.body,'$.State')='PhysicalCompleted',coalesce(json_extract(NEW.body,'$.Wcs.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Plc.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Upload.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Capture.Attempts'),0)) ON CONFLICT(id) DO UPDATE SET barcode=excluded.barcode,state=excluded.state,observed=excluded.observed,wcs=excluded.wcs,plc=excluded.plc,upload=excluded.upload,capture=excluded.capture,accepted=excluded.accepted,unknown=excluded.unknown,physical=excluded.physical,attempts=excluded.attempts; END;
CREATE TRIGGER parcel_operations_projection_insert AFTER INSERT ON parcel_operations BEGIN INSERT INTO parcel_history_projection(id,barcode,state,observed,wcs,plc,upload,capture,accepted,unknown,physical,attempts) VALUES(NEW.id,json_extract(NEW.body,'$.ParcelCode'),json_extract(NEW.body,'$.State'),julianday(json_extract(NEW.body,'$.ObservedAt')),json_extract(NEW.body,'$.Wcs.Request.Id'),json_extract(NEW.body,'$.Plc.Request.Id'),json_extract(NEW.body,'$.Upload.Request.Id'),json_extract(NEW.body,'$.Capture.Request.Id'),coalesce(json_extract(NEW.body,'$.Wcs.State')='Accepted',0),coalesce(json_extract(NEW.body,'$.Wcs.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Plc.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Upload.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Capture.State')='Unknown',0),json_extract(NEW.body,'$.State')='PhysicalCompleted',coalesce(json_extract(NEW.body,'$.Wcs.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Plc.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Upload.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Capture.Attempts'),0)) ON CONFLICT(id) DO UPDATE SET barcode=excluded.barcode,state=excluded.state,observed=excluded.observed,wcs=excluded.wcs,plc=excluded.plc,upload=excluded.upload,capture=excluded.capture,accepted=excluded.accepted,unknown=excluded.unknown,physical=excluded.physical,attempts=excluded.attempts; END;
CREATE TRIGGER parcel_operations_projection_update AFTER UPDATE ON parcel_operations BEGIN INSERT INTO parcel_history_projection(id,barcode,state,observed,wcs,plc,upload,capture,accepted,unknown,physical,attempts) VALUES(NEW.id,json_extract(NEW.body,'$.ParcelCode'),json_extract(NEW.body,'$.State'),julianday(json_extract(NEW.body,'$.ObservedAt')),json_extract(NEW.body,'$.Wcs.Request.Id'),json_extract(NEW.body,'$.Plc.Request.Id'),json_extract(NEW.body,'$.Upload.Request.Id'),json_extract(NEW.body,'$.Capture.Request.Id'),coalesce(json_extract(NEW.body,'$.Wcs.State')='Accepted',0),coalesce(json_extract(NEW.body,'$.Wcs.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Plc.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Upload.State')='Unknown',0) OR coalesce(json_extract(NEW.body,'$.Capture.State')='Unknown',0),json_extract(NEW.body,'$.State')='PhysicalCompleted',coalesce(json_extract(NEW.body,'$.Wcs.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Plc.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Upload.Attempts'),0)+coalesce(json_extract(NEW.body,'$.Capture.Attempts'),0)) ON CONFLICT(id) DO UPDATE SET barcode=excluded.barcode,state=excluded.state,observed=excluded.observed,wcs=excluded.wcs,plc=excluded.plc,upload=excluded.upload,capture=excluded.capture,accepted=excluded.accepted,unknown=excluded.unknown,physical=excluded.physical,attempts=excluded.attempts; END;
CREATE INDEX station_operation_time ON parcel_operations(julianday(json_extract(body,'$.Wcs.Request.PreparedAt')));
CREATE INDEX station_archive_time ON parcel_archives(julianday(json_extract(body,'$.Wcs.Request.PreparedAt')));
CREATE INDEX station_recognition_time ON parcel_audit(julianday(json_extract(detail,'$.Observation.ObservedAt'))) WHERE event='InputObserved' AND json_valid(detail);
INSERT INTO parcel_meta VALUES(1,0,0);
CREATE TABLE station_run_shifts(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,opened_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,detected_at TEXT,closed_at TEXT,status TEXT NOT NULL CHECK(status IN ('Open','Closed','Interrupted')),elapsed_ms REAL NOT NULL CHECK(elapsed_ms>=0),clock_adjusted INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX station_one_open_shift ON station_run_shifts(status) WHERE status='Open';
CREATE TABLE station_shift_totals(shift TEXT NOT NULL,position TEXT NOT NULL,recognitions INTEGER NOT NULL CHECK(recognitions>=0),requests INTEGER NOT NULL CHECK(requests>=0),assigned INTEGER NOT NULL CHECK(assigned>=0),rejected INTEGER NOT NULL CHECK(rejected>=0),unknown_count INTEGER NOT NULL CHECK(unknown_count>=0),manual_requests INTEGER NOT NULL CHECK(manual_requests>=0),PRIMARY KEY(shift,position));
CREATE TABLE station_metric_facts(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('observation','request')),owner TEXT NOT NULL,source_seq INTEGER,shift TEXT NOT NULL,fact_at TEXT NOT NULL,minute TEXT NOT NULL,position TEXT NOT NULL,recognitions INTEGER NOT NULL CHECK(recognitions IN (0,1)),requests INTEGER NOT NULL CHECK(requests IN (0,1)),assigned INTEGER NOT NULL CHECK(assigned IN (0,1)),rejected INTEGER NOT NULL CHECK(rejected IN (0,1)),unknown_count INTEGER NOT NULL CHECK(unknown_count IN (0,1)),manual_requests INTEGER NOT NULL CHECK(manual_requests IN (0,1)),reason_scope TEXT NOT NULL,reason_code TEXT NOT NULL,issues INTEGER NOT NULL CHECK(issues IN (0,1)));
CREATE UNIQUE INDEX station_observation_fact ON station_metric_facts(source_seq) WHERE source_seq IS NOT NULL;
CREATE INDEX station_fact_owner ON station_metric_facts(owner,kind);
CREATE INDEX station_fact_shift ON station_metric_facts(shift,kind);
CREATE INDEX station_exception_unknown ON station_metric_facts(owner) WHERE kind='request' AND unknown_count=1;
CREATE INDEX station_exception_rejected ON station_metric_facts(owner) WHERE kind='request' AND rejected=1;
CREATE INDEX station_exception_observation ON station_metric_facts(source_seq DESC) WHERE kind='observation' AND issues=1;
CREATE INDEX station_metrics_time ON station_metric_buckets(minute,position);
CREATE TABLE station_reason_buckets(shift TEXT NOT NULL,minute TEXT NOT NULL,position TEXT NOT NULL,scope TEXT NOT NULL,code TEXT NOT NULL,count INTEGER NOT NULL CHECK(count>=0),PRIMARY KEY(shift,minute,position,scope,code));
CREATE INDEX station_reasons_time ON station_reason_buckets(minute,scope,code);
CREATE TRIGGER station_fact_immutable BEFORE UPDATE ON station_metric_facts WHEN NEW.id<>OLD.id OR NEW.kind<>OLD.kind OR NEW.owner<>OLD.owner OR NEW.shift<>OLD.shift OR NEW.fact_at<>OLD.fact_at OR NEW.minute<>OLD.minute OR NEW.position<>OLD.position OR coalesce(NEW.source_seq,-1)<>coalesce(OLD.source_seq,-1) BEGIN SELECT RAISE(ABORT,'Original statistic attribution cannot change'); END;
CREATE TRIGGER station_fact_insert AFTER INSERT ON station_metric_facts BEGIN
  INSERT INTO station_metric_buckets VALUES(NEW.shift,NEW.minute,NEW.position,NEW.recognitions,NEW.requests,NEW.assigned,NEW.rejected,NEW.unknown_count,NEW.manual_requests) ON CONFLICT(shift,minute,position) DO UPDATE SET recognitions=recognitions+excluded.recognitions,requests=requests+excluded.requests,assigned=assigned+excluded.assigned,rejected=rejected+excluded.rejected,unknown_count=unknown_count+excluded.unknown_count,manual_requests=manual_requests+excluded.manual_requests;
  INSERT INTO station_shift_totals VALUES(NEW.shift,NEW.position,NEW.recognitions,NEW.requests,NEW.assigned,NEW.rejected,NEW.unknown_count,NEW.manual_requests) ON CONFLICT(shift,position) DO UPDATE SET recognitions=recognitions+excluded.recognitions,requests=requests+excluded.requests,assigned=assigned+excluded.assigned,rejected=rejected+excluded.rejected,unknown_count=unknown_count+excluded.unknown_count,manual_requests=manual_requests+excluded.manual_requests;
  INSERT INTO station_reason_buckets SELECT NEW.shift,NEW.minute,NEW.position,NEW.reason_scope,NEW.reason_code,NEW.issues WHERE NEW.issues>0 ON CONFLICT(shift,minute,position,scope,code) DO UPDATE SET count=count+excluded.count;
END;
CREATE TRIGGER station_fact_update AFTER UPDATE ON station_metric_facts BEGIN
  UPDATE station_metric_buckets SET recognitions=recognitions-OLD.recognitions+NEW.recognitions,requests=requests-OLD.requests+NEW.requests,assigned=assigned-OLD.assigned+NEW.assigned,rejected=rejected-OLD.rejected+NEW.rejected,unknown_count=unknown_count-OLD.unknown_count+NEW.unknown_count,manual_requests=manual_requests-OLD.manual_requests+NEW.manual_requests WHERE shift=OLD.shift AND minute=OLD.minute AND position=OLD.position;
  UPDATE station_shift_totals SET recognitions=recognitions-OLD.recognitions+NEW.recognitions,requests=requests-OLD.requests+NEW.requests,assigned=assigned-OLD.assigned+NEW.assigned,rejected=rejected-OLD.rejected+NEW.rejected,unknown_count=unknown_count-OLD.unknown_count+NEW.unknown_count,manual_requests=manual_requests-OLD.manual_requests+NEW.manual_requests WHERE shift=OLD.shift AND position=OLD.position;
  UPDATE station_reason_buckets SET count=count-OLD.issues WHERE OLD.issues>0 AND shift=OLD.shift AND minute=OLD.minute AND position=OLD.position AND scope=OLD.reason_scope AND code=OLD.reason_code;
  INSERT INTO station_reason_buckets SELECT NEW.shift,NEW.minute,NEW.position,NEW.reason_scope,NEW.reason_code,NEW.issues WHERE NEW.issues>0 ON CONFLICT(shift,minute,position,scope,code) DO UPDATE SET count=count+excluded.count;
END;